#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

REPO=/etc/nixos
KEY=$HOME/.ssh/id_ed25519
ENV_FILE=${XDG_STATE_HOME:-$HOME/.local/state}/wizards/backup.env
mkdir -p "$(dirname "$ENV_FILE")"
JSON=$REPO/hosts/storagebox.json
HOMELAB_KEY_AGE=$REPO/secrets/homelab/storagebox-key.age
LEGION_RESTIC_AGE=$REPO/secrets/legion/restic.age

recipient() { grep -oP "^\s*$1 = \"\K[^\"]+" "$REPO/secrets/secrets.nix"; }
restic_pass() { age -d -i "$KEY" "$REPO/secrets/homelab/restic.age"; }

banner "Backups: homelab and legion → Hetzner Storage Box"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Storage Box: SSH and snapshots"
say "You need a Storage Box (BX11, 1 TB). Its page is in the Hetzner Console,"
say "or in Robot (robot.hetzner.com → Storage Box) on older accounts."
open_url "https://console.hetzner.com/"
step "Open the Storage Box and turn on: SSH support, External reachability"
step "Turn on automatic snapshots (daily, keep 14): they protect the backups"
step "  even if homelab itself is broken into and deletes them"
step "Note the main username, it looks like u123456"
ask SB_MAIN "Main username (u123456):"
write_env SB_MAIN "$SB_MAIN"
note "Panel names move around; what matters is SSH on, external access on, snapshots on."
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Storage Box: one sub-account per machine"
say "Each machine gets its own sub-account, locked into its own folder, so one"
say "machine can't touch the other's backups."
step "Sub-accounts → create one with base directory homelab, SSH support on"
step "Create a second with base directory legion, SSH support on"
step "Give each a password and save both in Vaultwarden (Storage Box homelab / legion)"
ask SUB_HOMELAB "homelab sub-account username (u123456-sub1):"
ask SUB_LEGION "legion sub-account username (u123456-sub2):"
write_env SUB_HOMELAB "$SUB_HOMELAB"
write_env SUB_LEGION "$SUB_LEGION"
host_key=$(ssh-keyscan -p 23 -t ed25519 "$SUB_HOMELAB.your-storagebox.de" 2>/dev/null | awk '{print $2" "$3}')
legion_key=$(ssh-keyscan -p 23 -t ed25519 "$SUB_LEGION.your-storagebox.de" 2>/dev/null | awk '{print $2" "$3}')
if [[ -z $host_key ]]; then
  warn "no answer from $SUB_HOMELAB.your-storagebox.de:23 — is SSH on and the name right?"
  exit 1
fi
[[ $host_key == "$legion_key" ]] || warn "the two sub-accounts report different host keys; using homelab's"
cat >"$JSON" <<EOF
{
  "hostKey": "$host_key",
  "homelab": {"user": "$SUB_HOMELAB", "host": "$SUB_HOMELAB.your-storagebox.de"},
  "legion": {"user": "$SUB_LEGION", "host": "$SUB_LEGION.your-storagebox.de"}
}
EOF
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$JSON"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "homelab's key for its sub-account"
if [[ -f $HOMELAB_KEY_AGE ]] && ! confirm "homelab already has a Storage Box key. Make a new one?"; then
  note "keeping the existing key"
else
  tmp=$(mktemp -d)
  ssh-keygen -q -t ed25519 -N "" -C "homelab restic" -f "$tmp/key"
  age -R <(recipient lux; recipient homelab) -o "$HOMELAB_KEY_AGE" "$tmp/key"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$HOMELAB_KEY_AGE"
  say "Now ssh-copy-id asks for the homelab sub-account password once:"
  ssh-copy-id -p 23 -s -i "$tmp/key.pub" -o StrictHostKeyChecking=accept-new "$SUB_HOMELAB@$SUB_HOMELAB.your-storagebox.de"
  rm -rf "$tmp"
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "legion's key and restic password"
say "legion signs in with your usual ~/.ssh/id_ed25519."
say "ssh-copy-id asks for the legion sub-account password once:"
ssh-copy-id -p 23 -s -i "$KEY.pub" -o StrictHostKeyChecking=accept-new "$SUB_LEGION@$SUB_LEGION.your-storagebox.de"
restic_pass | age -R <(recipient lux) -o "$LEGION_RESTIC_AGE"
printf '  %s✓ wrote%s %s (same restic password as homelab)\n' "$GREEN" "$RESET" "$LEGION_RESTIC_AGE"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Commit, deploy homelab, rebuild legion"
say "Commits storagebox.json and the two secrets, then deploys both machines."
if confirm "Commit and deploy now?"; then
  git -C "$REPO" add "$JSON" "$HOMELAB_KEY_AGE" "$LEGION_RESTIC_AGE"
  git -C "$REPO" diff --cached --quiet || git -C "$REPO" commit -q -m "chore(backup): storage box for offsite backups"
  if ! nh os switch "$REPO" -H homelab --target-host homelab --build-host homelab; then
    warn "the homelab deploy reported an error. If services look fine, make it the boot default:"
    note "nh os boot $REPO -H homelab --target-host homelab --build-host homelab && ssh -t homelab sudo reboot"
    pause "Fix it, then Enter to continue"
  fi
  nh os switch "$REPO" || { warn "legion rebuild failed"; SKIPPED+=("rebuild legion: rebuild"); }
else
  SKIPPED+=("commit + deploy-homelab + rebuild")
fi

# ── 6 ────────────────────────────────────────────────────────────────────
stage "First backups"
say "The first offsite run uploads everything (tens of GB) and takes hours;"
say "later runs only send what changed. They run in the background."
if confirm "Start them now?"; then
  ssh -t homelab sudo systemctl start --no-block backup-vaultwarden restic-backups-files restic-backups-offsite
  sudo systemctl start --no-block restic-backups-laptop
  printf '  %s✓ started%s\n' "$GREEN" "$RESET"
fi
note "watch homelab:  ssh -t homelab journalctl -fu restic-backups-offsite"
note "watch legion:   journalctl -fu restic-backups-laptop"
note "list snapshots: ssh -t homelab sudo restic-offsite snapshots"
note "A failed run sends a Telegram message (homelab) or a desktop notification (legion)."
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "The emergency sheet"
say "If both machines die, this paper is how you get everything back. The"
say "restic password is on it; everything else comes out of the backups."
sheet=$(cat <<EOF
BACKUP EMERGENCY SHEET — $(date +%F)

restic password (all repositories):
  $(restic_pass)

Hetzner Storage Box: main user $SB_MAIN
  homelab sub-account: $SUB_HOMELAB   (folder homelab)
  legion sub-account:  $SUB_LEGION   (folder legion)
  sub-account passwords: ______________________  ______________________

Hetzner account login (for the panel and box snapshots): ______________________
Vaultwarden master password: ______________________
Vaultwarden 2FA recovery code: ______________________

Restore from any Linux machine:
  1. ~/.ssh/config:  Host storagebox
                       HostName $SUB_LEGION.your-storagebox.de
                       User $SUB_LEGION
                       Port 23
  2. restic -r sftp:storagebox:restic snapshots
  3. restic -r sftp:storagebox:restic restore latest --target ~/restore
     (legion's ~/.ssh/id_ed25519 decrypts every secret in the nixos repo)
  For homelab, put the homelab sub-account in the Host block instead.
  Local copies: homelab /srv/backup/restic, /var/backup/{photos,files}
EOF
)
printf '%s\n' "$sheet" | sed 's/^/  /'
if confirm "Print it now (lp)?"; then
  printf '%s\n' "$sheet" | lp && printf '  %s✓ sent to the printer%s\n' "$GREEN" "$RESET" || warn "printing failed; copy it by hand"
fi
note "Fill in the blanks by hand. Keep it somewhere that isn't next to the server."
pause "Enter clears the screen (the password leaves the terminal)."

finish
}

run_wizard "$@"; exit
